package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var CurRec DateRec
var dateFileLines []string
var dateFileIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func IsLeap() bool {
	return WsLeapFlag == "Y"
}

func parseNum(s string) int64 {
	var v int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			v = v * 10
		}
	}
	return v
}

func formatNum(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	r := v % mod
	if r < 0 {
		r += mod
	}
	s := fmt.Sprintf("%0*d", width, r)
	if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	br := bufio.NewReader(f)
	dateFileLines = nil
	for {
		line, err := br.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				if len(line) > 0 {
					if len(line) > 0 && line[len(line)-1] == '\r' {
						line = line[:len(line)-1]
					}
					dateFileLines = append(dateFileLines, line)
				}
				break
			} else {
				fmt.Fprintln(os.Stderr, err)
				os.Exit(1)
			}
		} else {
			line = line[:len(line)-1]
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			dateFileLines = append(dateFileLines, line)
		}
	}
	dateFileIdx = 0
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	f.Close()
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n", formatNum(WsValid, 2), formatNum(WsBadMonth, 2), formatNum(WsBadDay, 2))
}

func ReadPara() {
	if dateFileIdx >= len(dateFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := dateFileLines[dateFileIdx]
	dateFileIdx++
	if len(line) < 12 {
		line += strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	CurRec.DtId = line[0:4]
	CurRec.DtYyyy = parseNum(line[4:8])
	CurRec.DtMm = parseNum(line[8:10])
	CurRec.DtDd = parseNum(line[10:12])
}

func ProcessPara() {
	LeapPara()
	if CurRec.DtMm < 1 || CurRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Printf("%s BAD MONTH %s\n", CurRec.DtId, formatNum(CurRec.DtMm, 2))
	} else {
		DaysPara()
		if CurRec.DtDd < 1 || CurRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Printf("%s BAD DAY %s MAX %s\n", CurRec.DtId, formatNum(CurRec.DtDd, 2), formatNum(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Printf("%s VALID %s-%s-%s\n", CurRec.DtId, formatNum(CurRec.DtYyyy, 4), formatNum(CurRec.DtMm, 2), formatNum(CurRec.DtDd, 2))
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = (CurRec.DtYyyy / 4) % 10000
	WsR4 = (CurRec.DtYyyy % 4) % 1000
	WsQ = (CurRec.DtYyyy / 100) % 10000
	WsR100 = (CurRec.DtYyyy % 100) % 1000
	WsQ = (CurRec.DtYyyy / 400) % 10000
	WsR400 = (CurRec.DtYyyy % 400) % 1000
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch CurRec.DtMm {
	case 2:
		if IsLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = WsMaxDay % 100
}

func main() {
	MainPara()
}
